"""Tiny loan-quote HTTP API.

POST /quote  {"principal": 200000, "annual_rate": 0.06, "months": 360}
             -> {"monthly_payment": "...", "total_interest": "...", "total_paid": "..."}
GET  /health -> {"status": "ok"}
"""

import json
from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, getcontext
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

getcontext().prec = 50
TWO_PLACES = Decimal("0.01")


class ValidationError(Exception):
    pass


def _to_decimal(value, field):
    if isinstance(value, bool) or value is None:
        raise ValidationError(f"{field} must be a number")
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        raise ValidationError(f"{field} must be a number")


def calculate_quote(principal, annual_rate, months):
    """Return (monthly_payment, total_interest, total_paid) as Decimals."""
    principal = _to_decimal(principal, "principal")
    annual_rate = _to_decimal(annual_rate, "annual_rate")
    months = _to_decimal(months, "months")

    if principal <= 0:
        raise ValidationError("principal must be positive")
    if months <= 0:
        raise ValidationError("months must be positive")

    n = int(months)
    monthly_rate = annual_rate / Decimal(12)

    if monthly_rate == 0:
        monthly_payment = principal / Decimal(n)
    else:
        factor = (Decimal(1) + monthly_rate) ** (-n)
        monthly_payment = principal * monthly_rate / (Decimal(1) - factor)

    total_paid = monthly_payment * Decimal(n)
    total_interest = total_paid - principal

    q = lambda d: d.quantize(TWO_PLACES, rounding=ROUND_HALF_UP)
    return q(monthly_payment), q(total_interest), q(total_paid)


class QuoteHandler(BaseHTTPRequestHandler):
    def _send_json(self, status, payload):
        body = json.dumps(payload).encode()
        self.send_response(status)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def do_GET(self):
        if self.path == "/health":
            self._send_json(200, {"status": "ok"})
        else:
            self._send_json(404, {"error": "not found"})

    def do_POST(self):
        if self.path != "/quote":
            self._send_json(404, {"error": "not found"})
            return
        try:
            length = int(self.headers.get("Content-Length", 0))
            data = json.loads(self.rfile.read(length) or b"{}")
            for field in ("principal", "annual_rate", "months"):
                if field not in data:
                    raise ValidationError(f"missing field: {field}")
            monthly_payment, total_interest, total_paid = calculate_quote(
                data["principal"], data["annual_rate"], data["months"]
            )
        except (ValidationError, json.JSONDecodeError, ValueError) as exc:
            self._send_json(400, {"error": str(exc)})
            return
        self._send_json(200, {
            "monthly_payment": str(monthly_payment),
            "total_interest": str(total_interest),
            "total_paid": str(total_paid),
        })

    def log_message(self, *args):  # keep test output clean
        pass


def run(host="127.0.0.1", port=8737):
    server = ThreadingHTTPServer((host, port), QuoteHandler)
    print(f"listening on http://{host}:{port}", flush=True)
    server.serve_forever()


if __name__ == "__main__":
    run()

